// 纯工具函数，无重型依赖，可安全静态 import

// ── Base58 ──────────────────────────────────────────────
const B58 = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz'
function b58enc(buf) {
  let n = 0n
  for (const b of buf) n = (n << 8n) | BigInt(b)
  let s = ''
  while (n > 0n) { s = B58[Number(n % 58n)] + s; n /= 58n }
  for (const b of buf) { if (b !== 0) break; s = '1' + s }
  return s
}
function b58dec(str, len) {
  let n = 0n
  for (const c of str) {
    const i = B58.indexOf(c)
    if (i < 0) throw new Error('bad char: ' + c)
    n = n * 58n + BigInt(i)
  }
  const buf = new Uint8Array(len)
  for (let i = len - 1; i >= 0; i--) { buf[i] = Number(n & 0xffn); n >>= 8n }
  return buf
}

// ── Hex helpers ─────────────────────────────────────────
function toHex(val) {
  if (typeof val === 'bigint') return '0x' + val.toString(16)
  const s = String(val)
  if (s.startsWith('0x') || s.startsWith('0X')) return s
  return '0x' + BigInt(s).toString(16)
}
function hexToBytes(hex, len) {
  const h = toHex(hex).replace(/^0x/i, '').padStart(len * 2, '0')
  const b = new Uint8Array(len)
  for (let i = 0; i < len; i++) b[i] = parseInt(h.slice(i * 2, i * 2 + 2), 16)
  return b
}
function bytesToHex(buf) {
  return '0x' + [...buf].map(b => b.toString(16).padStart(2, '0')).join('')
}

// ── Pack 116 bytes: commitment(32) + secret(32) + nullifier(32) + token(20) ──
function packHash(note) {
  const buf = new Uint8Array(116)
  buf.set(hexToBytes(note.commitment, 32), 0)
  buf.set(hexToBytes(note.secret, 32), 32)
  buf.set(hexToBytes(note.nullifier, 32), 64)
  buf.set(hexToBytes(note.token || '0x' + '0'.repeat(40), 20), 96)
  return buf
}
function bufToBigInt(buf) {
  let n = 0n
  for (const b of buf) n = (n << 8n) | BigInt(b)
  return n
}
function unpackHash(buf) {
  return {
    commitment: bufToBigInt(buf.slice(0, 32)).toString(),
    secret:     bufToBigInt(buf.slice(32, 64)).toString(),
    nullifier:  bufToBigInt(buf.slice(64, 96)).toString(),
    token:      bytesToHex(buf.slice(96, 116)),
  }
}

// ── Public API ───────────────────────────────────────────
// Format: cloakcash-{chainId}-{amount}-{base58(116 bytes)}
export function encodeTicket(note) {
  return `cloakcash-${note.chainId}-${note.amount}-${b58enc(packHash(note))}`
}

export function decodeTicket(str) {
  try {
    str = str.trim()
    if (!str.startsWith('cloakcash-')) return null
    const rest = str.slice('cloakcash-'.length)
    const dash1 = rest.indexOf('-')
    const dash2 = rest.indexOf('-', dash1 + 1)
    if (dash1 < 0 || dash2 < 0) return null
    const chainId = Number(rest.slice(0, dash1))
    const amount  = rest.slice(dash1 + 1, dash2)
    const b58part = rest.slice(dash2 + 1)
    const fields  = unpackHash(b58dec(b58part, 116))
    return { chainId, amount, ...fields }
  } catch { return null }
}

// ── Storage: only encoded string + metadata ──────────────
const KEY = 'cloakcash_tickets2'

function _load() {
  try { return JSON.parse(localStorage.getItem(KEY) || '[]') } catch { return [] }
}
function _save(rows) {
  localStorage.setItem(KEY, JSON.stringify(rows))
}

// Returns decoded ticket objects (with commitment as key), plus status/savedAt/chainId
export function loadTickets() {
  return _load().map(r => {
    const decoded = decodeTicket(r.encoded)
    if (!decoded) return null
    return { ...decoded, status: r.status, savedAt: r.savedAt, txHash: r.txHash, seq: r.seq || 0 }
  }).filter(Boolean)
}

export function saveTicket(note) {
  const rows = _load()
  const encoded = encodeTicket(note)
  if (rows.find(r => r.encoded === encoded)) return
  const seq = rows.reduce((m, r) => Math.max(m, r.seq || 0), 0) + 1
  rows.push({ encoded, status: 'pending', savedAt: Date.now(), seq })
  _save(rows)
}

export function deleteTicketsByChain(chainId) {
  _save(_load().filter(r => {
    const d = decodeTicket(r.encoded)
    return d?.chainId !== chainId
  }))
}

export function deleteTicket(commitment) {
  _save(_load().filter(r => {
    const d = decodeTicket(r.encoded)
    return d?.commitment !== commitment
  }))
}

export function updateTicketStatus(commitment, status) {
  _save(_load().map(r => {
    const d = decodeTicket(r.encoded)
    return d?.commitment === commitment ? { ...r, status } : r
  }))
}

export function updateTicketTxHash(commitment, txHash) {
  _save(_load().map(r => {
    const d = decodeTicket(r.encoded)
    return d?.commitment === commitment ? { ...r, txHash } : r
  }))
}

export function markTicketUsed(commitment) { updateTicketStatus(commitment, 'used') }
